function ensureObstacles(width,height){if(s.obstaclesGenerated)return;s.obstacles={};const occupied=new Set(s.buildings.map(b=>b.x+","+b.y));for(let y=0;y<height;y++)for(let x=0;x<width;x++){const key=x+","+y;if(occupied.has(key)||(x>=8&&x<=14&&y>=5&&y<=10))continue;const biome=terrainKind(x,y,width,height),hash=(x*31+y*73+x*y*17+19)%100;let type=null;if((biome==="forest"||biome==="grove")&&hash<13)type="forest";else if((biome==="rock"||biome==="hill")&&hash<16)type="rock";else if(hash===7||hash===41)type="ruins";else if(biome==="meadow"&&hash<4)type="marsh";if(type)s.obstacles[key]=type}s.obstaclesGenerated=true;save()}
